    {
        try
        {
            if (Gst.GObject.Object.TryGetOrFabricate(self) is not TimelineElement managed)
            {
                return ChainUpGetLayerPriority(self);
            }

            return managed.OnGetLayerPriority();
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return default;
        }
    }

    [UnmanagedCallersOnly(CallConvs = new[] { typeof(CallConvCdecl) })]
    private static int GetNaturalFramerateTrampoline(nint self, int* framerateN, int* framerateD)
    {
        try
        {
            if (Gst.GObject.Object.TryGetOrFabricate(self) is not TimelineElement managed)
            {
                return (ChainUpGetNaturalFramerate(self, framerateN, framerateD)) ? 1 : 0;
            }

            int framerateNValue = default;
            int framerateDValue = default;

            try
            {
                bool result = managed.OnGetNaturalFramerate(out framerateNValue, out framerateDValue);
                *framerateN = framerateNValue;
                *framerateD = framerateDValue;
                return (result) ? 1 : 0;
            }
            finally
            {
            }
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
            return default;
        }
    }
}
